    "functions": [
        {
            "name": "add_repair_evidence",
            "returns": "uuid",
            "arguments": "p_contract_id uuid, p_storage_path text, p_evidence_type text, p_notes text DEFAULT NULL::text",
            "definition": "CREATE OR REPLACE FUNCTION public.add_repair_evidence(p_contract_id uuid, p_storage_path text, p_evidence_type text, p_notes text DEFAULT NULL::text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\nDECLARE\r\n    v_evidence_id UUID;\r\n    v_expected_prefix TEXT;\r\nBEGIN\r\n    IF p_evidence_type NOT IN (\r\n        'before', 'progress', 'after'\r\n    ) OR p_evidence_type IS NULL THEN\r\n        RAISE EXCEPTION 'Invalid evidence type';\r\n    END IF;\r\n\r\n    IF p_storage_path IS NULL\r\n       OR length(p_storage_path) > 500 THEN\r\n        RAISE EXCEPTION 'Invalid storage path';\r\n    END IF;\r\n\r\n    v_expected_prefix :=\r\n        'contracts/' || p_contract_id::text || '/';\r\n\r\n    IF left(p_storage_path, length(v_expected_prefix))\r\n       <> v_expected_prefix THEN\r\n        RAISE EXCEPTION 'Incorrect storage path';\r\n    END IF;\r\n\r\n    IF NOT EXISTS (\r\n        SELECT 1\r\n        FROM public.contracts ct\r\n        JOIN public.contractors co\r\n          ON co.id = ct.contractor_id\r\n        WHERE ct.id = p_contract_id\r\n          AND co.owner_id = auth.uid()\r\n          AND co.verification_status = 'approved'\r\n          AND ct.status = 'in_progress'\r\n    ) THEN\r\n        RAISE EXCEPTION 'Not authorized to upload evidence';\r\n    END IF;\r\n\r\n    -- Ensure the uploaded object really exists\r\n    -- and belongs to the caller.\r\n    IF NOT EXISTS (\r\n        SELECT 1\r\n        FROM storage.objects obj\r\n        WHERE obj.bucket_id = 'repair-evidence'\r\n          AND obj.name = p_storage_path\r\n          AND obj.owner_id = auth.uid()::text\r\n    ) THEN\r\n        RAISE EXCEPTION 'Uploaded image not found or not owned by user';\r\n    END IF;\r\n\r\n    INSERT INTO public.work_evidence(\r\n        contract_id, uploaded_by, storage_path,\r\n        evidence_type, notes\r\n    )\r\n    VALUES (\r\n        p_contract_id, auth.uid(), p_storage_path,\r\n        p_evidence_type, left(p_notes, 2000)\r\n    )\r\n    RETURNING id INTO v_evidence_id;\r\n\r\n    RETURN v_evidence_id;\r\nEND;\r\n$function$\n",
            "volatility": "v",
            "search_path": [
                "search_path=\"\""
            ],
            "security_definer": true
        },
        {
            "name": "assign_repair_job",
            "returns": "uuid",
            "arguments": "p_complaint_id uuid, p_contractor_id uuid, p_title text, p_budget numeric, p_approved_amount numeric, p_award_reason text, p_deadline timestamp with time zone DEFAULT NULL::timestamp with time zone",
            "definition": "CREATE OR REPLACE FUNCTION public.assign_repair_job(p_complaint_id uuid, p_contractor_id uuid, p_title text, p_budget numeric, p_approved_amount numeric, p_award_reason text, p_deadline timestamp with time zone DEFAULT NULL::timestamp with time zone)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\nDECLARE\r\n    v_admin_municipality UUID;\r\n    v_complaint_municipality UUID;\r\n    v_complaint_status TEXT;\r\n    v_job_id UUID;\r\n    v_contract_id UUID;\r\nBEGIN\r\n    IF auth.uid() IS NULL\r\n       OR NOT private.has_role(\r\n           ARRAY['municipal_admin']\r\n       ) THEN\r\n        RAISE EXCEPTION 'Permission denied';\r\n    END IF;\r\n\r\n    SELECT municipality_id\r\n    INTO v_admin_municipality\r\n    FROM public.profiles\r\n    WHERE id = auth.uid();\r\n\r\n    IF v_admin_municipality IS NULL THEN\r\n        RAISE EXCEPTION\r\n          'Admin municipality is not configured';\r\n    END IF;\r\n\r\n    SELECT status, municipality_id\r\n    INTO v_complaint_status, v_complaint_municipality\r\n    FROM public.complaints\r\n    WHERE id = p_complaint_id\r\n    FOR UPDATE;\r\n\r\n    IF NOT FOUND THEN\r\n        RAISE EXCEPTION 'Complaint not found';\r\n    END IF;\r\n\r\n    IF v_complaint_municipality\r\n       IS DISTINCT FROM v_admin_municipality THEN\r\n        RAISE EXCEPTION 'Wrong municipality';\r\n    END IF;\r\n\r\n    IF v_complaint_status <> 'verified' THEN\r\n        RAISE EXCEPTION\r\n          'Complaint must be verified first';\r\n    END IF;\r\n\r\n    IF NOT EXISTS (\r\n        SELECT 1\r\n        FROM public.contractors\r\n        WHERE id = p_contractor_id\r\n          AND verification_status = 'approved'\r\n    ) THEN\r\n        RAISE EXCEPTION\r\n          'Contractor is not approved';\r\n    END IF;\r\n\r\n    IF p_title IS NULL\r\n       OR length(trim(p_title)) < 5\r\n       OR p_award_reason IS NULL\r\n       OR length(trim(p_award_reason)) < 5 THEN\r\n    