            "definition": "CREATE OR REPLACE FUNCTION public.review_duplicate(p_candidate_id uuid, p_decision text, p_remarks text DEFAULT NULL::text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\nDECLARE\r\n    v_admin_municipality UUID;\r\n    v_complaint_id UUID;\r\n    v_original_id UUID;\r\n    v_review_status TEXT;\r\n    v_complaint_municipality UUID;\r\n    v_original_municipality UUID;\r\n    v_complaint_status TEXT;\r\n    v_original_status TEXT;\r\n    v_existing_duplicate UUID;\r\nBEGIN\r\n    -- Only municipal admins can review duplicates.\r\n    IF auth.uid() IS NULL OR\r\n       NOT private.has_role(\r\n           ARRAY['municipal_admin']\r\n       ) THEN\r\n        RAISE EXCEPTION 'Municipal admin required';\r\n    END IF;\r\n\r\n    IF p_decision IS NULL OR\r\n       p_decision NOT IN (\r\n           'duplicate', 'not_duplicate'\r\n       ) THEN\r\n        RAISE EXCEPTION 'Invalid decision';\r\n    END IF;\r\n\r\n    SELECT municipality_id\r\n    INTO v_admin_municipality\r\n    FROM public.profiles\r\n    WHERE id = auth.uid();\r\n\r\n    IF v_admin_municipality IS NULL THEN\r\n        RAISE EXCEPTION 'Admin municipality missing';\r\n    END IF;\r\n\r\n    -- Lock the candidate review record.\r\n    SELECT\r\n        complaint_id,\r\n        candidate_id,\r\n        review_status\r\n    INTO\r\n        v_complaint_id,\r\n        v_original_id,\r\n        v_review_status\r\n    FROM public.duplicate_candidates\r\n    WHERE id = p_candidate_id\r\n    FOR UPDATE;\r\n\r\n    IF NOT FOUND THEN\r\n        RAISE EXCEPTION 'Duplicate candidate not found';\r\n    END IF;\r\n\r\n    IF v_review_status <> 'pending' THEN\r\n        RAISE EXCEPTION\r\n            'This duplicate has already been reviewed';\r\n    END IF;\r\n\r\n    -- Lock both complaints in deterministic order\r\n    -- to reduce deadlock risk.\r\n    PERFORM 1\r\n    FROM public.complaints\r\n    WHERE id IN (v_complaint_id, v_original_id)\r\n    ORDER BY id\r\n    FOR UPDATE;\r\n\r\n    SELECT municipality_id, status, duplicate_of\r\n    INTO\r\n        v_complaint_municipality,\r\n        v_complaint_status,\r\n        v_existing_duplicate\r\n    FROM public.complaints\r\n    WHERE id = v_complaint_id;\r\n\r\n    IF NOT FOUND THEN\r\n        RAISE EXCEPTION 'Reported complaint missing';\r\n    END IF;\r\n\r\n    SELECT municipality_id, status\r\n    INTO v_original_municipality, v_original_status\r\n    FROM public.complaints\r\n    WHERE id = v_original_id;\r\n\r\n    IF NOT FOUND THEN\r\n        RAISE EXCEPTION 'Original complaint missing';\r\n    END IF;\r\n\r\n    IF v_complaint_municipality\r\n       IS DISTINCT FROM v_admin_municipality\r\n       OR v_original_municipality\r\n       IS DISTINCT FROM v_admin_municipality THEN\r\n        RAISE EXCEPTION 'Municipality mismatch';\r\n    END IF;\r\n\r\n    IF p_decision = 'duplicate' THEN\r\n\r\n        -- Only unprocessed submitted reports\r\n        -- can be linked as duplicates.\r\n        IF v_complaint_status <> 'submitted'\r\n           OR v_original_status IN ('rejected')\r\n           OR v_existing_duplicate IS NOT NULL\r\n        THEN\r\n            RAISE EXCEPTION\r\n                'Complaint cannot be merged';\r\n        END IF;\r\n\r\n        -- Prevent merging into an existing\r\n        -- duplicate or creating a chain/cycle.\r\n        IF EXISTS (\r\n            SELECT 1\r\n            FROM public.complaints\r\n            WHERE id = v_original_id\r\n              AND duplicate_of IS NOT NULL\r\n        ) THEN\r\n            RAISE EXCEPTION\r\n                'Cannot merge into another duplicate';\r\n        END IF;\r\n\r\n        IF EXISTS (\r\n            SELECT 1\r\n            FROM public.complaints\r\n            WHERE duplicate_of = v_complaint_id\r\n        ) THEN\r\n            RAISE EXCEPTION\r\n                'Complaint already has linked reports';\r\n        END IF;\r\n\r\n        UPDATE public.complaints\r\n        SET duplicate_of = v_original_id,\r\n            updated_at = now()\r\n        WHERE id = v_complaint_id;\r\n\r\n        -- Record the merge in the stage timeline.\r\n        -- No fake status transition is created.\r\n        INSERT INTO public.complaint_updates (\r\n            complaint_id,\r\n            changed_by,\r\n            old_status,\r\n            new_status,\r\n            remarks\r\n        )\r\n        VALUES (\r\n            v_complaint_id,\r\n            auth.uid(),\r\n            v_complaint_status,\r\n            v_complaint_status,\r\n            'Linked to complaint ' ||\r\n            v_original_id::text ||\r\n            CASE\r\n                WHEN nullif(trim(p_remarks), '') IS NOT NULL\r\n                THEN ': ' || left(trim(p_remarks), 1000)\r\n                ELSE ''\r\n            END\r\n        );\r\n\r\n    END IF;\r\n\r\n    UPDATE public.duplicate_candidates\r\n    SET review_status = p_decision\r\n    WHERE id = p_candidate_id;\r\n\r\n    INSERT INTO public.audit_logs (\r\n        actor_id,\r\n        action,\r\n        entity_type,\r\n        entity_id,\r\n        details\r\n    )\r\n    VALUES (\r\n        auth.uid(),\r\n        'duplicate_review',\r\n        'duplicate_candidate',\r\n        p_candidate_id,\r\n        jsonb_build_object(\r\n            'decision', p_decision,\r\n            'complaint_id', v_complaint_id,\r\n            'original_id', v_original_id,\r\n            'remarks', left(p_remarks, 1000)\r\n        )\r\n    );\r\n\r\nEND;\r\n$function$\n",
