            "definition": "CREATE OR REPLACE FUNCTION public.save_priority_rule(p_category text, p_base_score integer, p_age_weight integer, p_support_weight integer)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\nDECLARE\r\n    v_municipality UUID;\r\n    v_rule_id UUID;\r\nBEGIN\r\n\r\n    -- Only authenticated municipal admins.\r\n    IF auth.uid() IS NULL\r\n       OR NOT private.has_role(\r\n           ARRAY['municipal_admin']\r\n       ) THEN\r\n        RAISE EXCEPTION\r\n            'Municipal admin permission required';\r\n    END IF;\r\n\r\n    SELECT municipality_id\r\n    INTO v_municipality\r\n    FROM public.profiles\r\n    WHERE id = auth.uid();\r\n\r\n    IF v_municipality IS NULL THEN\r\n        RAISE EXCEPTION\r\n            'Admin municipality is not configured';\r\n    END IF;\r\n\r\n    -- Validate category.\r\n    IF p_category IS NULL\r\n       OR p_category NOT IN (\r\n           'pothole',\r\n           'streetlight',\r\n           'garbage',\r\n           'other'\r\n       ) THEN\r\n        RAISE EXCEPTION 'Invalid complaint category';\r\n    END IF;\r\n\r\n    -- Validate priority settings.\r\n    IF p_base_score IS NULL\r\n       OR p_base_score NOT BETWEEN 0 AND 100\r\n       OR p_age_weight IS NULL\r\n       OR p_age_weight NOT BETWEEN 0 AND 20\r\n       OR p_support_weight IS NULL\r\n       OR p_support_weight NOT BETWEEN 0 AND 20\r\n    THEN\r\n        RAISE EXCEPTION 'Invalid priority rule values';\r\n    END IF;\r\n\r\n    -- Update existing rule or create new rule.\r\n    INSERT INTO public.priority_rules (\r\n        municipality_id,\r\n        category,\r\n        base_score,\r\n        age_weight,\r\n        support_weight,\r\n        updated_at\r\n    )\r\n    VALUES (\r\n        v_municipality,\r\n        p_category,\r\n        p_base_score,\r\n        p_age_weight,\r\n        p_support_weight,\r\n        now()\r\n    )\r\n    ON CONFLICT (municipality_id, category)\r\n    DO UPDATE SET\r\n        base_score = EXCLUDED.base_score,\r\n        age_weight = EXCLUDED.age_weight,\r\n        support_weight = EXCLUDED.support_weight,\r\n        updated_at = now()\r\n    RETURNING id INTO v_rule_id;\r\n\r\n    -- Record privileged change.\r\n    INSERT INTO public.audit_logs (\r\n        actor_id,\r\n        action,\r\n        entity_type,\r\n        entity_id,\r\n        details\r\n    )\r\n    VALUES (\r\n        auth.uid(),\r\n        'priority_rule_saved',\r\n        'priority_rule',\r\n        v_rule_id,\r\n        jsonb_build_object(\r\n            'category', p_category,\r\n            'base_score', p_base_score,\r\n            'age_weight', p_age_weight,\r\n            'support_weight', p_support_weight,\r\n            'municipality_id', v_municipality\r\n        )\r\n    );\r\n\r\n    RETURN v_rule_id;\r\nEND;\r\n$function$\n",
