            "definition": "CREATE OR REPLACE FUNCTION public.start_repair(p_contract_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\nDECLARE\r\n    v_status TEXT;\r\n    v_complaint_id UUID;\r\n    v_complaint_status TEXT;\r\nBEGIN\r\n    SELECT ct.status, j.complaint_id, c.status\r\n    INTO v_status, v_complaint_id, v_complaint_status\r\n    FROM public.contracts ct\r\n    JOIN public.contractors co\r\n      ON co.id = ct.contractor_id\r\n    JOIN public.jobs j ON j.id = ct.job_id\r\n    JOIN public.complaints c ON c.id = j.complaint_id\r\n    WHERE ct.id = p_contract_id\r\n      AND co.owner_id = auth.uid()\r\n      AND co.verification_status = 'approved'\r\n    FOR UPDATE OF ct, c;\r\n\r\n    IF NOT FOUND THEN\r\n        RAISE EXCEPTION 'Contract not found or access denied';\r\n    END IF;\r\n\r\n    IF NOT (\r\n        (v_status = 'awarded' AND v_complaint_status = 'assigned')\r\n        OR\r\n        (v_status = 'rework' AND v_complaint_status = 'rework_required')\r\n    ) THEN\r\n        RAISE EXCEPTION 'Invalid repair start transition';\r\n    END IF;\r\n\r\n    UPDATE public.contracts\r\n    SET status = 'in_progress'\r\n    WHERE id = p_contract_id;\r\n\r\n    UPDATE public.complaints\r\n    SET status = 'in_progress',\r\n        updated_at = now()\r\n    WHERE id = v_complaint_id;\r\n\r\n    INSERT INTO public.audit_logs(\r\n        actor_id, action, entity_type, entity_id\r\n    )\r\n    VALUES (\r\n        auth.uid(), 'repair_started',\r\n        'contract', p_contract_id\r\n    );\r\nEND;\r\n$function$\n",
