            "definition": "CREATE OR REPLACE FUNCTION public.verify_contractor(p_contractor_id uuid, p_decision text, p_remarks text DEFAULT NULL::text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\nDECLARE\r\n    v_admin_municipality UUID;\r\n    v_contractor_municipality UUID;\r\n    v_owner_id UUID;\r\n    v_old_status TEXT;\r\nBEGIN\r\n\r\n    IF auth.uid() IS NULL\r\n       OR NOT private.has_role(\r\n           ARRAY['municipal_admin']\r\n       ) THEN\r\n        RAISE EXCEPTION\r\n            'Municipal admin permission required';\r\n    END IF;\r\n\r\n    IF p_decision IS NULL\r\n       OR p_decision NOT IN (\r\n           'approved', 'rejected'\r\n       ) THEN\r\n        RAISE EXCEPTION\r\n            'Decision must be approved or rejected';\r\n    END IF;\r\n\r\n    SELECT municipality_id\r\n    INTO v_admin_municipality\r\n    FROM public.profiles\r\n    WHERE id = auth.uid();\r\n\r\n    IF v_admin_municipality IS NULL THEN\r\n        RAISE EXCEPTION\r\n            'Admin municipality is not configured';\r\n    END IF;\r\n\r\n    SELECT\r\n        municipality_id,\r\n        owner_id,\r\n        verification_status\r\n    INTO\r\n        v_contractor_municipality,\r\n        v_owner_id,\r\n        v_old_status\r\n    FROM public.contractors\r\n    WHERE id = p_contractor_id\r\n    FOR UPDATE;\r\n\r\n    IF NOT FOUND THEN\r\n        RAISE EXCEPTION\r\n            'Contractor not found';\r\n    END IF;\r\n\r\n    IF v_contractor_municipality\r\n       IS DISTINCT FROM v_admin_municipality THEN\r\n        RAISE EXCEPTION\r\n            'Contractor belongs to another municipality';\r\n    END IF;\r\n\r\n    IF v_old_status <> 'pending' THEN\r\n        RAISE EXCEPTION\r\n            'Only pending applications can be reviewed';\r\n    END IF;\r\n\r\n    IF v_owner_id = auth.uid() THEN\r\n        RAISE EXCEPTION\r\n            'You cannot approve your own application';\r\n    END IF;\r\n\r\n    IF p_decision = 'approved' THEN\r\n\r\n        UPDATE public.profiles\r\n        SET role = 'contractor',\r\n            updated_at = now()\r\n        WHERE id = v_owner_id\r\n          AND role = 'citizen';\r\n\r\n        IF NOT FOUND THEN\r\n            RAISE EXCEPTION\r\n                'Applicant must have a citizen profile';\r\n        END IF;\r\n\r\n    END IF;\r\n\r\n    UPDATE public.contractors\r\n    SET verification_status = p_decision\r\n    WHERE id = p_contractor_id;\r\n\r\n    INSERT INTO public.audit_logs(\r\n        actor_id,\r\n        action,\r\n        entity_type,\r\n        entity_id,\r\n        details\r\n    )\r\n    VALUES (\r\n        auth.uid(),\r\n        'contractor_verification',\r\n        'contractor',\r\n        p_contractor_id,\r\n        jsonb_build_object(\r\n            'old_status', v_old_status,\r\n            'decision', p_decision,\r\n            'remarks', left(p_remarks, 2000)\r\n        )\r\n    );\r\n\r\n    INSERT INTO public.notifications(\r\n        user_id,\r\n        title,\r\n        body\r\n    )\r\n    VALUES (\r\n        v_owner_id,\r\n        CASE\r\n            WHEN p_decision = 'approved'\r\n            THEN 'Contractor Approved'\r\n            ELSE 'Contractor Application Rejected'\r\n        END,\r\n        CASE\r\n            WHEN p_decision = 'approved'\r\n            THEN 'Your contractor account has been approved.'\r\n            ELSE 'Your contractor application was rejected.'\r\n        END\r\n    );\r\n\r\nEND;\r\n$function$\n",
